//Solo se ejecuta si la key existe
SET color 'Hola' XX

GET color

//NX Solo se ejecuta si la key no existe
SET colorini blue NX 

get colorini

// EX 2 - Borra el valor que almacena la key despues de 2 seg

SET color red  EX 2

GET color

//SETRANGE Nos sirve para actualizar una porcion de una cadena de texto

SETRANGE color 1 nacuajo

GET color

//INCR Nos sirve para incrementar numeros
SET age 20

INCR age
